/* ===== 设置页布局 (二级导航) ===== */
.sa-settings-layout {
  display: flex;
  gap: 16px;
}
.sa-settings-nav {
  display: flex; flex-direction: column;
  gap: 4px;
  width: 150px;
  flex-shrink: 0;
}
.sa-settings-nav-item {
