.sa-btn:hover { background: rgba(60,50,38,0.11); border-color: rgba(60,50,38,0.2); color: var(--sa-text); }
.sa-btn:active { transform: scale(0.97); }
.sa-btn-group { display: flex; gap: 8px; flex-wrap: wrap; }

.sa-btn-primary { background: linear-gradient(135deg, var(--sa-accent), #c9a96e); color: #2a2520; border-color: transparent; box-shadow: 0 2px 12px rgba(201,169,110,0.35); }
.sa-btn-primary:hover { background: linear-gradient(135deg, var(--sa-accent2), #d8bd82); box-shadow: 0 4px 18px rgba(201,169,110,0.5); }
.sa-btn-danger { background: var(--sa-red-dim); border-color: rgba(177,58,58,0.3); color: var(--sa-red); }
.sa-btn-danger:hover { background: rgba(177,58,58,0.25); border-color: rgba(177,58,58,0.5); color: #b13a3a; }
.sa-btn-success { background: rgba(91,138,114,0.12); border-color: rgba(91,138,114,0.3); color: #3d6b54; }
.sa-btn-success:hover { background: rgba(91,138,114,0.22); border-color: rgba(91,138,114,0.5); color: #3d6b54; }
.sa-btn-warn { background: rgba(201,169,110,0.12); border-color: rgba(201,169,110,0.3); color: #a07f48; }
.sa-btn-warn:hover { background: rgba(201,169,110,0.22); border-color: rgba(201,169,110,0.5); color: #8a6a2e; }
