.sa-checkbox-grid label:hover, .sa-radio-group label:hover { color: var(--sa-text); }
.sa-no-trans-label { grid-column: 1 / -1; flex-wrap: wrap; }
.sa-no-trans-input { all: unset; width: 110px; height: 24px; padding: 2px 6px; margin-left: 4px; font-size: 12px; border: 1px solid rgba(60,50,38,0.2); border-radius: 4px; background: rgba(60,50,38,0.06); color: var(--sa-text); box-sizing: border-box; vertical-align: middle; }
.sa-no-trans-input:focus { border-color: var(--sa-accent); outline: none; }

input[type="checkbox"], input[type="radio"] {
  all: unset; width: 16px; height: 16px; border: 2px solid rgba(60,50,38,0.2);
  flex-shrink: 0; cursor: pointer; transition: all 0.15s; position: relative;
  display: inline-flex; align-items: center; justify-content: center;
