/**
 * ui/panelEvents.js
 * 面板事件绑定与交互逻辑
 * 依赖: config.js, utils.js, storage.js, summary.js, worldbook.js, api.js,
 *       ui/panel.js, ui/renderer.js, errorHandler.js
